from typing import List
from collections import Counter

def maxScoreWords(words: List[str], letters: List[str], score: List[int]) -> int:
    def can_form(word_count, available_letters):
        for char, count in word_count.items():
            if available_letters[char] < count:
                return False
        return True

    def dfs(index, current_score, available_letters):
        if index == len(words):
            return current_score

        # Option 1: Skip the current word
        max_score = dfs(index + 1, current_score, available_letters)

        # Option 2: Include the current word if possible
        word_count = Counter(words[index])
        if can_form(word_count, available_letters):
            new_available_letters = available_letters - word_count
            word_score = sum(score[ord(c) - ord('a')] for c in words[index])
            max_score = max(max_score, dfs(index + 1, current_score + word_score, new_available_letters))

        return max_score

    available_letters = Counter(letters)
    return dfs(0, 0, available_letters)
